def normalise_iban(text):
    if not isinstance(text, str):
        return None
    compact = "".join(text.split()).replace("-", "").upper()
    letters = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    digits = "0123456789"
    if len(compact) < 15 or len(compact) > 34:
        return None
    if compact[0] not in letters or compact[1] not in letters or compact[2] not in digits or compact[3] not in digits:
        return None
    if any(char not in letters and char not in digits for char in compact):
        return None
    rotated = compact[4:] + compact[:4]
    number = "".join(char if char in digits else str(letters.index(char) + 10) for char in rotated)
    return compact if int(number) % 97 == 1 else None
